guide.simple_bytestorage_scripting.examp:
§eЗабирати все зі скрині§r
§bvar c = side("up");
function tick() { if (c) c.pull(); }§r

§eТримати 64 вугілля в печі§r
§bvar f = side("north");
function tick() {
  if (!f) return;
  var need = 64 - f.count("minecraft:coal");
  if (need > 0) f.push("minecraft:coal", need);
}§r

§eАвтокрафт за браку§r
§bfunction tick() {
  if (net.count("minecraft:stick") < 64)
    net.craft("minecraft:stick", 64);
}§r

§eПеренесення між двома скринями§r
§bvar a = side("up"), b = side("down");
function tick() { if (a && b) a.move(b); }§r
